import sqlite3
c = sqlite3.connect(":memory:")
c.executescript("""
create table shopping_purchase(order_id int, user_id int, amt int, dt text);
insert into shopping_purchase values
 (1,10,12000,'2026-11-22'),(2,NULL,8000,'2026-11-22'),(2,11,8000,'2026-11-22');
""")
checks = {
  "완전성: user_id 비었나": "select count(*) from shopping_purchase where user_id is null",
  "유일성: order_id 겹치나": """select count(*) from (select order_id from shopping_purchase
                               group by order_id having count(*)>1)""",
  "신선도: 오늘(11-23) 치가 있나": """select case when max(dt) >= '2026-11-23' then 0 else 1 end
                                  from shopping_purchase""",
}
for name, q in checks.items():
    bad = c.execute(q).fetchone()[0]
    print("실패" if bad else "통과", name, bad)
# 실패 완전성: user_id 비었나 1
# 실패 유일성: order_id 겹치나 1
# 실패 신선도: 오늘(11-23) 치가 있나 1
